INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Head Spin', 'Geauga Lake', 'Steel', 'Vekoma', 'Vekoma Boomerang', 116.5, 47.0, 935.0, 3, 108, 1996, '1996', 'year', '2007-09-16', 'day', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Head Spin' AND park = 'Geauga Lake');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Head Spin' AND c.park = 'Geauga Lake' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
