-- 111: the rest of Geauga Lake from Carter's RCDB screenshots, 2026-10-31.
-- Head Spin (Vekoma Boomerang 1996-2007), Little Dipper (NAD Comet Jr., by
-- 1962 - stored 1952 - to 1975), Raging Wolf Bobs (Dinn wood, 1988 to 16 Jun
-- 2007), Steel Venom (Intamin Impulse 2000-2006), Thunderhawk (Vekoma SLC
-- 1998-2007), Villain (CCI wood 2000-2007), Wild Mouse (Schiff, "perhaps 1958
-- to the 1970s" - stored 1958-1970), X-Flight (Vekoma Flying Dutchman
-- 2001-2006), Zyclone (Pinfari Zyklon Z47, 1976-1980).
-- Relocations linked (home = where it went):
--   Head Spin -> Flying Cobras (Carowinds); Steel Venom -> Possessed (Dorney
--   Park); Thunderhawk -> Thunderhawk (Michigan's Adventure); X-Flight ->
--   Firehawk (Kings Island; RCDB's relocation line was below the screenshot,
--   but the move is well documented and the Kings Island row opens 2007).
-- Not linked: Wild Mouse -> Chippewa Lake Park; Zyclone -> Holiday World /
-- Jolly Roger as Firecracker - no rows here. Safe to run twice.
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Flying Cobras' AND h.park = 'Carowinds' AND (c.id = h.id OR (c.name = 'Head Spin' AND c.park = 'Geauga Lake'));
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Possessed' AND h.park = 'Dorney Park' AND (c.id = h.id OR (c.name = 'Steel Venom' AND c.park = 'Geauga Lake'));
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Thunderhawk' AND h.park = 'Michigan''s Adventure' AND (c.id = h.id OR (c.name = 'Thunderhawk' AND c.park = 'Geauga Lake'));
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Firehawk' AND h.park = 'Kings Island' AND (c.id = h.id OR (c.name = 'X-Flight' AND c.park = 'Geauga Lake'));
